import{z as i,x as s,o as t,c as D,q as l,j as B,D as A,d as a,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"能力维度的体系","description":"","frontmatter":{"title":"能力维度的体系","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ef-capability-taxonomy.md","filePath":"llm/ef-capability-taxonomy.md","lastUpdated":1791413859000}'),d={name:"llm/ef-capability-taxonomy.md"};function p(m,E,C,h,c,F){const r=s("Mermaid");return t(),D("div",null,[E[2]||(E[2]=l('<h1 id="能力维度的体系" tabindex="-1">能力维度的体系 <a class="header-anchor" href="#能力维度的体系" aria-label="Permalink to &quot;能力维度的体系&quot;">​</a></h1><div class="epigraph"><p>维度体系不是分类学游戏：它决定哪些声明有对应的仪器。没有格子的声明，就只能靠感觉说话。</p><footer>—— 据 Liang 等 HELM 2022、Srivastava 等 BIG-bench 2022、Ribeiro 等 CheckList 2020 整理</footer></div><p><a href="/llm/ef-arena-methodology">上一课</a>给了名次及其区间，但一个聚合标量回答不了「强在哪、弱在哪」。本课写能力维度的体系：轴从哪来、怎么操作化成格子、覆盖矩阵怎么读。主干已有散点的维度课——<a href="/llm/long-context-eval">长上下文</a>、<a href="/llm/dangerous-capability-eval">危险能力</a>、对齐深钻的三根轴；本课不重讲某一轴，写的是把它们装配成体系的规则。下一课的新任务设计默认你已经在矩阵上找到了空格。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单一总分的三宗罪：加权平均掩盖短板——代码满分可以补齐安全挂零；轴之间相关但不等价——数学分高不等于推理好，可能只是背了题；声明失去落点——「我们提升了推理能力」这句话若没有一格卷子对着，就不可证伪。各家榜单各带一把尺，同一模型在不同体系的名次差好几位，因为体系本身在测不同的构念组合。<span class="marginnote">「构念」是心理测量学的行话，指看不见摸不着、只能靠一组题目间接测量的抽象能力，比如「推理」「鲁棒性」。卷子之于构念，就像温度计读数之于温度——读数本身不是温度，是间接证据。所以先想清楚构念是什么，再挑卷子，顺序反了就变成「手里有什么卷子就宣称测什么」。</span>缺口是：把散落的基准映射到一张自家的覆盖矩阵上，让每个对外声明都能指到行与列。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>HELM 的三维格是可抄的骨架：<strong>场景</strong>（任务 × 领域 × 语言）× <strong>指标</strong>（准确、校准、鲁棒、公平、效率）× <strong>扰动</strong>（同义改写、格式变化、干扰项）。<span class="marginnote">扰动一格长什么样：把「请总结这篇文章」改写成「帮我概括一下上文」再考同一道题，或把表格从竖排改成横排。如果准确率从 90% 掉到 55%，说明模型背下来的是格式而不是能力——这种「换个说法就露馅」的脆弱性，正是扰动维度要抓的东西。</span>落地成四步。第一步<strong>选轴</strong>：从产品声明与风险清单倒推——做客服就先有指令服从、多轮状态、拒答分寸，做研究助手先有长文档与引用；危险能力与安全轴按<a href="/llm/dangerous-capability-eval">危险能力评测</a>的单轴规范单列。第二步<strong>映射存量</strong>：把现有基准逐个填进格子，一格多卷正常，注明各自口径。第三步<strong>读矩阵</strong>：一格多卷且高相关的，留一把主尺；多格空缺的，就是新卷子的清单——接下一课的设计流程。第四步<strong>版本化</strong>：轴会扩容（智能体、多模态都是后来者），每次扩容写进体系变更记录，跨版本的剖面不可直接减。</p>',7)),(t(),B(n,null,{default:A(()=>[o(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20CL%5B%22%E4%BA%A7%E5%93%81%E5%A3%B0%E6%98%8E%E4%B8%8E%E9%A3%8E%E9%99%A9%E6%B8%85%E5%8D%95%22%5D%20--%3E%20AX%5B%22%E9%80%89%E8%BD%B4%22%5D%0A%20%20AX%20--%3E%20GRID%5B%22%E5%9C%BA%E6%99%AF%20%C3%97%20%E6%8C%87%E6%A0%87%20%C3%97%20%E6%89%B0%E5%8A%A8%E7%9A%84%E6%A0%BC%E5%AD%90%22%5D%0A%20%20GRID%20--%3E%20MAP%5B%22%E5%AD%98%E9%87%8F%E5%9F%BA%E5%87%86%E9%80%90%E6%A0%BC%E6%98%A0%E5%B0%84%22%5D%0A%20%20MAP%20--%3E%20READ%7B%22%E8%AF%BB%E8%A6%86%E7%9B%96%E7%9F%A9%E9%98%B5%22%7D%0A%20%20READ%20--%3E%7C%22%E4%B8%80%E6%A0%BC%E5%A4%9A%E5%8D%B7%22%7C%20DEDUP%5B%22%E7%95%99%E4%B8%BB%E5%B0%BA%EF%BC%8C%E5%85%B6%E4%BD%99%E9%99%8D%E9%A2%91%22%5D%0A%20%20READ%20--%3E%7C%22%E7%A9%BA%E6%A0%BC%22%7C%20NEW%5B%22%E6%96%B0%E8%AF%84%E6%B5%8B%E8%AE%BE%E8%AE%A1%E6%B8%85%E5%8D%95%22%5D%0A%20%20GRID%20--%3E%20VER%5B%22%E8%BD%B4%E6%89%A9%E5%AE%B9%E8%AE%B0%E5%85%A5%E7%89%88%E6%9C%AC%E5%8F%98%E6%9B%B4%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("体系的价值来自"),e("strong",null,"构念—仪器—声明"),a("的对齐链：每个声明对应一个构念，每个构念至少一格，每格至少一把标定过的仪器。加权总分为什么该弃用：权重是隐式的价值声明，把「客服场景的安全」和「竞赛数学」放进同一加权，等于宣称二者可互相补偿；分剖面把补偿的可能拿掉，短板自己会站出来。扰动维度的机制来自 CheckList：能力不是在干净样例上的准确率，而是同义改写后还稳不稳——把扰动当一列格子，鲁棒就从「附带观察」变成「可发布的数字」。轴的相关性还要定期重算：模型族换代后，原本高相关的两轴可能解耦，昨天的冗余卷子今天是独立证据。")],-1)),(t(),B(n,null,{default:A(()=>[o(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20CL%5B%22%E5%AF%B9%E5%A4%96%E5%A3%B0%E6%98%8E%3A%3Cbr%2F%3E%E3%80%8E%E6%8F%90%E5%8D%87%E4%BA%86%E6%8E%A8%E7%90%86%E8%83%BD%E5%8A%9B%E3%80%8F%22%5D%20--%3E%20C%5B%22%E6%9E%84%E5%BF%B5%E5%AE%9A%E4%B9%89%3A%20%E6%8E%A8%E7%90%86%3Cbr%2F%3E%E5%86%99%E6%98%8E%E6%A8%AA%E8%B7%A8%E6%95%B0%E5%AD%A6%2F%E4%BB%A3%E7%A0%81%2F%E8%A7%84%E5%88%92%22%5D%0A%20%20C%20--%3E%20G%5B%22%E6%A0%BC%E5%AD%90%3A%20%E6%95%B0%E5%AD%A6%E5%8D%B7%20%E4%BB%A3%E7%A0%81%E5%8D%B7%20%E8%A7%84%E5%88%92%E5%8D%B7%22%5D%0A%20%20G%20--%3E%20I%5B%22%E4%BB%AA%E5%99%A8%3A%20%E6%AF%8F%E6%A0%BC%E8%87%B3%E5%B0%91%E4%B8%80%E6%8A%8A%3Cbr%2F%3E%E6%A0%87%E5%AE%9A%E8%BF%87%E7%9A%84%E5%8D%B7%E5%AD%90%22%5D%0A%20%20I%20--%3E%20E%5B%22%E5%8F%AF%E8%AF%81%E4%BC%AA%E8%AF%81%E6%8D%AE%3A%3Cbr%2F%3E%E5%88%86%E5%89%96%E9%9D%A2%E6%95%B0%E5%AD%97%20%E5%8A%A0%20%E5%8C%BA%E9%97%B4%22%5D%0A%20%20CL%20-.-%3E%7C%22%E6%B2%A1%E6%9C%89%E6%A0%BC%E5%AD%90%E5%AF%B9%E5%BA%94%22%7C%20X%5B%22%E4%B8%8D%E5%8F%AF%E8%AF%81%E4%BC%AA%3A%20%E5%8F%AA%E8%83%BD%E9%9D%A0%E6%84%9F%E8%A7%89%E8%AF%B4%E8%AF%9D%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">一格多卷不是浪费：两把卷子相关 0.95 时，另一把降频作对表；相关 0.5 时，它们是两个构念，格子应该一分为二。相关性矩阵是体系健康的年度体检。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>体系会膨胀成新的官僚：格子多到没人跑得完，矩阵就从地图变成装饰——覆盖矩阵必须与下一课的功效预算联动，空格按声明优先级排队，不是先来先填。构念重叠是常态：「推理」横跨数学、代码、规划，一格一轴的整洁是假象，要在构念定义里写明重叠处归谁。体系也不裁决真值：它只保证「测什么」被钉死，「测得多准」归统计功效课，「对齐类轴怎么测」归对齐深钻课。最后，长尾格子（低资源语言、罕见领域）可能长期空着，声明里就不要出现它们。<span class="marginnote">「矩阵变官僚」不是修辞：假设 30 个格子、每格 2000 题、每次发布全量跑一遍，评测算力很快超过一次小模型微调的成本。所以空格必须按对外声明的优先级排队——先补要拿来发声明的格子，而不是谁先提出谁先进矩阵。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>维度体系把声明钉到格子：场景 × 指标 × 扰动，HELM 三维是可抄的骨架。</li><li>轴从产品声明与风险清单倒推，不从「别人有什么基准」顺推。</li><li>弃用加权总分，发布分剖面；短板与补偿关系由读者看见。</li><li>一格多卷看相关性定主尺；空格接新任务设计，扩容记版本。</li><li>出处：Liang 等 HELM 2022；Srivastava 等 BIG-bench 2022；Ribeiro 等 CheckList 2020，按本课程整理。</li></ul>',5))])}const b=i(d,[["render",p]]);export{g as __pageData,b as default};
